export const isExternalUrl = (href) => {
    return /^https?:\/\//i.test(href) || href.startsWith("//");
};
export const resolveBaseUrl = (path = "", baseUrl = "/") => {
    if (isExternalUrl(path)) {
        return path;
    }
    const cleanPath = path.startsWith("/") ? path.slice(1) : path;
    const normalizedBase = baseUrl.endsWith("/") ? baseUrl : `${baseUrl}/`;
    return `${normalizedBase}${cleanPath}`;
};
export function url(path = "", baseOverride) {
    let baseUrl = "/";
    try {
        // import.meta.env.BASE_URL is statically replaced by Vite at build time;
        // the try-catch handles non-Vite environments (e.g. CMS admin preview)
        // where import.meta.env may be undefined at runtime.
        baseUrl = baseOverride ?? import.meta.env.BASE_URL ?? "/";
    }
    catch {
        baseUrl = baseOverride ?? "/";
    }
    return resolveBaseUrl(path, baseUrl);
}
